use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl ExpnId { # [doc = " The ID of the theoretical expansion that generates freshly parsed, unexpanded AST."] # [doc = " Invariant: we do not create any ExpnId with local_id == 0 and krate != 0."] pub const fn root () -> ExpnId { ExpnId { krate : LOCAL_CRATE , local_id : ExpnIndex :: ZERO } } # [inline] pub fn expn_hash (self) -> ExpnHash { HygieneData :: with (| data | data . expn_hash (self)) } # [inline] pub fn from_hash (hash : ExpnHash) -> Option < ExpnId > { HygieneData :: with (| data | data . expn_hash_to_expn_id . get (& hash) . copied ()) } # [inline] pub fn as_local (self) -> Option < LocalExpnId > { if self . krate == LOCAL_CRATE { Some (LocalExpnId :: from_raw (self . local_id)) } else { None } } # [inline] # [track_caller] pub fn expect_local (self) -> LocalExpnId { self . as_local () . unwrap () } # [inline] pub fn expn_data (self) -> ExpnData { HygieneData :: with (| data | data . expn_data (self) . clone ()) } # [inline] pub fn is_descendant_of (self , ancestor : ExpnId) -> bool { if ancestor == ExpnId :: root () || ancestor == self { return true ; } if ancestor . krate != self . krate { return false ; } HygieneData :: with (| data | data . is_descendant_of (self , ancestor)) } # [doc = " `expn_id.outer_expn_is_descendant_of(ctxt)` is equivalent to but faster than"] # [doc = " `expn_id.is_descendant_of(ctxt.outer_expn())`."] # [inline] pub fn outer_expn_is_descendant_of (self , ctxt : SyntaxContext) -> bool { HygieneData :: with (| data | data . is_descendant_of (self , data . outer_expn (ctxt))) } # [doc = " Returns span for the macro which originally caused this expansion to happen."] # [doc = ""] # [doc = " Stops backtracing at include! boundary."] pub fn expansion_cause (mut self) -> Option < Span > { let mut last_macro = None ; loop { if self == ExpnId :: root () { break ; } let expn_data = self . expn_data () ; if expn_data . kind == ExpnKind :: Macro (MacroKind :: Bang , sym :: include) { break ; } self = expn_data . call_site . ctxt () . outer_expn () ; last_macro = Some (expn_data . call_site) ; } last_macro } }